#pragma once
#include "webui_shared.h"
inline std::string get_config_page(std::string_view version) {
return webui::start("Full configuration","settings")+R"CONFIG(
<style>
.config-layout{display:grid;grid-template-columns:218px minmax(0,1fr);gap:24px;align-items:start}.config-sidebar{position:sticky;top:20px}.config-sidebar button{display:flex;justify-content:space-between;width:100%;min-height:40px;border:0;border-radius:10px;margin-bottom:3px;background:transparent;font-size:13px;text-align:left;padding:8px 12px}.config-sidebar button[aria-pressed=true]{background:var(--surface-soft);color:var(--accent)}.config-toolbar{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:14px;margin-bottom:20px;align-items:center}.config-toolbar .check-label{font-size:12px}.config-mobile-category{display:none}.config-group{padding:0;overflow:hidden;margin-bottom:18px}.config-group summary{cursor:pointer;list-style:none;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:20px 24px;font-size:17px;font-weight:700;min-height:65px}.config-group summary::-webkit-details-marker{display:none}.config-group summary:after{content:'+';color:var(--accent);font-size:22px}.config-group[open] summary:after{content:'−'}.config-group .group-fields{padding:0 24px}.config-field{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:22px;border-top:1px solid var(--line);padding:20px 0;align-items:start}.config-field label{font-size:14px;color:var(--ink);margin:0 0 5px}.config-field .field-help{font-size:12px;line-height:1.55;color:var(--muted);margin:7px 0}.config-field code{font-size:10px;color:var(--muted)}.config-field.changed{border-left:3px solid var(--accent);padding-left:13px}.config-field input[type=checkbox]{margin:0}.boolean-control{display:flex;align-items:center;gap:10px;min-height:46px;padding:11px 14px;border:1px solid var(--line);border-radius:11px;background:var(--bg)}.secret-clear{font-size:11px!important;min-height:40px;margin-top:6px!important}.secret-clear input{width:17px;height:17px}.restart-tag{font-size:10px;color:var(--warning);display:block;margin-top:5px}.save-bar{position:sticky;bottom:14px;display:flex;justify-content:space-between;align-items:center;gap:16px;padding:16px 20px;background:var(--surface);border:1px solid var(--line);border-radius:17px;box-shadow:0 3px 30px #0004;z-index:10;margin-top:22px}.save-bar strong{font-size:14px}.save-bar .hint{font-size:11px}.save-bar .row{gap:8px}.config-loading{padding:40px;text-align:center;color:var(--muted)}dialog{width:min(620px,calc(100vw - 28px));max-height:85dvh;border:1px solid var(--line);border-radius:22px;background:var(--surface);color:var(--ink);padding:25px;box-shadow:var(--shadow)}dialog::backdrop{background:#071014b8}dialog h2{margin-bottom:10px}.review-list{max-height:45dvh;overflow:auto;margin:20px 0}.review-change{padding:14px 0;border-top:1px solid var(--line);font-size:13px;overflow-wrap:anywhere}.review-change small{display:block;margin-top:5px}.review-value{color:var(--accent);margin-top:4px;white-space:pre-wrap}.dialog-actions{display:flex;justify-content:flex-end;gap:10px}.config-description{max-width:650px}.restart-notice{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:20px;border:1px solid var(--accent);border-radius:14px;padding:16px;font-size:13px;background:var(--surface-soft)}.config-title-actions{display:flex;gap:8px;flex-shrink:0}
@media(max-width:900px){.config-layout{grid-template-columns:minmax(0,1fr)}.config-sidebar{display:none}.config-mobile-category{display:block;margin-bottom:16px}.config-field{gap:16px;grid-template-columns:minmax(0,1fr) minmax(0,1fr)}}
@media(max-width:760px){.config-field{grid-template-columns:minmax(0,1fr);gap:12px;padding:19px 0}.config-group summary{padding:18px}.config-group .group-fields{padding:0 18px}.config-toolbar{grid-template-columns:minmax(0,1fr)}.config-toolbar .check-label{min-height:32px}.save-bar{bottom:calc(91px + env(safe-area-inset-bottom));padding:12px;gap:10px;flex-wrap:wrap}.save-bar>.row{margin-left:auto}.save-bar button{font-size:12px;padding:9px 12px}.page-heading{flex-wrap:wrap}.config-title-actions{width:100%}.config-title-actions .button,.config-title-actions button{flex:1}.restart-notice{flex-wrap:wrap}.config-description{font-size:13px}}
</style>
<div class="page-heading"><div><div class="eyebrow">Make it yours</div><h1>Full configuration</h1><p class="config-description">Every frame setting, neatly in one place. Search for an option, make your edits, then review what will change.</p></div><div class="config-title-actions"><a class="button quiet" href="/#remote">Back to frame</a><button id="reload-config" class="quiet">Reload</button></div></div>
<div id="config-error" class="notice" role="alert" hidden></div>
<div id="restart-notice" class="restart-notice" hidden><span>Saved. Restart the frame to apply settings marked “Restart needed”.</span><button id="restart-frame">Restart frame</button></div>
<div class="config-toolbar"><label style="margin:0"><span class="sr-only">Search all settings</span><input id="config-search" type="search" placeholder="Search settings, descriptions, or config keys…" autocomplete="off"></label><label class="check-label"><input id="changed-only" type="checkbox">Changed options only</label></div>
<label class="config-mobile-category" for="config-category">Section<select id="config-category"><option value="">All sections</option></select></label>
<p id="config-count" class="status" aria-live="polite" style="margin-bottom:18px">Loading all settings…</p>
<div class="config-layout"><aside id="config-sections" class="config-sidebar" aria-label="Configuration sections"></aside><form id="config-form" novalidate><div id="config-fields"><div class="card config-loading">Connecting to your frame…</div></div><div id="no-settings" class="card empty" hidden>No matching settings. Try another search or section.</div><div id="save-bar" class="save-bar" hidden><div><strong id="pending-count">All changes saved</strong><div class="hint">Only edited options are sent to your frame.</div></div><div class="row"><button id="discard-config" type="button" class="quiet" disabled>Discard</button><button id="review-config" type="submit" class="primary" disabled>Review changes</button></div></div></form></div>
<dialog id="config-review" aria-labelledby="review-heading"><h2 id="review-heading">Review your changes</h2><p class="hint">Your current settings stay active until you save.</p><div id="review-list" class="review-list"></div><p id="review-note" class="hint" style="margin-bottom:20px"></p><div class="dialog-actions"><button id="cancel-review" type="button" class="quiet">Keep editing</button><button id="save-config" type="button" class="primary">Save configuration</button></div></dialog>
<script>
'use strict';
(()=>{
 const {$,request,toast}=FrameUI;let model=null,controls=new Map(),category='',busy=false;
 const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 function error(message){$('config-error').textContent=message||'';$('config-error').hidden=!message;}
 function value(f){const c=controls.get(f.id);if(f.secret)return c.clear.checked?{clear:true}:c.input.value?{value:c.input.value}:null;if(f.type==='boolean')return c.input.checked;if(f.type==='list')return c.input.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(f.type==='integer'||f.type==='number')return c.input.value===''?'':Number(c.input.value);return c.input.value;}
 function edits(){if(!model)return [];return model.fields.filter(f=>f.secret?value(f)!==null:JSON.stringify(value(f))!==JSON.stringify(f.value));}
 function setBusy(value){busy=value;for(const c of controls.values()){c.input.disabled=value;if(c.clear)c.clear.disabled=value;}$('save-config').disabled=value;$('reload-config').disabled=value;$('cancel-review').disabled=value;update();}
 function update(){const changed=edits();for(const f of model?model.fields:[])controls.get(f.id).row.classList.toggle('changed',changed.includes(f));$('save-bar').hidden=!changed.length;$('pending-count').textContent=changed.length?changed.length+' unsaved change'+(changed.length===1?'':'s'):'All changes saved';$('review-config').disabled=busy||!changed.length;$('discard-config').disabled=busy||!changed.length;filter();}
 function filter(){if(!model)return;const search=$('config-search').value.trim().toLowerCase(),changed=edits(),only=$('changed-only').checked;let visible=0;
  for(const group of document.querySelectorAll('.config-group')){let count=0;for(const f of model.fields.filter(f=>f.group===group.dataset.group)){const c=controls.get(f.id),show=(!category||f.group===category)&&(!only||changed.includes(f))&&(!search||(f.label+' '+f.help+' '+f.id+' '+f.group).toLowerCase().includes(search));c.row.hidden=!show;if(show){count++;visible++;}}group.hidden=!count;if(count&&(search||category||only))group.open=true;}
  $('config-count').textContent=visible+' of '+model.fields.length+' options · '+new Set(model.fields.map(f=>f.group)).size+' sections';$('no-settings').hidden=visible>0;
  for(const b of $('config-sections').querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.dataset.group===category));$('config-category').value=category;
 }
 function render(){controls=new Map();$('config-fields').replaceChildren();$('config-sections').replaceChildren();$('config-category').replaceChildren(new Option('All sections',''));const groups=[...new Set(model.fields.map(f=>f.group))];
  const all=node('button','All settings');all.type='button';all.dataset.group='';all.addEventListener('click',()=>{category='';filter();});$('config-sections').append(all);
  for(const name of groups){const b=node('button',name);b.type='button';b.dataset.group=name;b.addEventListener('click',()=>{category=name;filter();$('config-fields').scrollIntoView({block:'start'});});$('config-sections').append(b);$('config-category').add(new Option(name,name));const group=node('details',undefined,'card config-group');group.dataset.group=name;group.open=groups.indexOf(name)<2;group.append(node('summary',name));const fields=node('div',undefined,'group-fields');group.append(fields);$('config-fields').append(group);if(name==='Google Photos'){const link=node('a','Open Google Photos importer','button');link.href='/google_photos_setup';fields.append(link);}
   for(const f of model.fields.filter(f=>f.group===name)){const row=node('div',undefined,'config-field'),description=node('div'),label=node('label',f.label),id='option-'+f.id;label.htmlFor=id;description.append(label,node('p',f.help,'field-help'),node('code',f.id));if(f.restart)description.append(node('span','Restart needed','restart-tag'));const editor=node('div');let input;
    if(f.type==='string'&&!f.secret&&f.choices.length&&f.id!=='display.resolution'){input=node('select');const choices=f.choices.includes(f.value)?f.choices:[f.value,...f.choices];for(const choice of choices)input.add(new Option(choice,choice));input.value=f.value;}
    else if(f.type==='list'){input=node('textarea');input.rows=3;input.value=f.value.join('\n');}
    else if(f.type==='boolean'){input=node('input');input.type='checkbox';input.checked=f.value;const toggle=node('label',undefined,'boolean-control');toggle.htmlFor=id;toggle.append(input,node('span','Enabled'));editor.append(toggle);}
    else {input=node('input');input.type=f.secret?'password':f.type==='integer'||f.type==='number'?'number':'text';input.value=f.secret?'':f.value;input.autocomplete=f.secret?'new-password':'off';if(f.type==='integer'||f.type==='number'){input.min=f.min;input.max=f.max;input.step=f.type==='integer'?'1':'any';input.required=true;}else input.maxLength=8192;
      if(f.secret)input.placeholder=f.configured?'Configured · blank keeps current':'Not configured';
      let choices=f.choices;if(f.id==='mqtt.timezone'&&Intl.supportedValuesOf){try{choices=['UTC',...Intl.supportedValuesOf('timeZone')];}catch{}}
      if(choices.length){const list=node('datalist');list.id=id+'-choices';for(const choice of choices)list.append(new Option(choice,choice));input.setAttribute('list',list.id);editor.append(list);}
    }
    input.id=id;input.dataset.key=f.id;input.setAttribute('aria-describedby',id+'-help');description.id=id+'-help';if(f.type!=='boolean')editor.prepend(input);let clear=null;
    if(f.secret){clear=node('input');clear.type='checkbox';clear.id=id+'-clear';const remove=node('label',undefined,'check-label secret-clear');remove.htmlFor=clear.id;remove.append(clear,node('span','Clear saved value'));editor.append(remove);clear.addEventListener('change',()=>{if(clear.checked)input.value='';update();});}
    input.addEventListener('input',()=>{if(clear&&input.value)clear.checked=false;update();});input.addEventListener('change',update);row.append(description,editor);fields.append(row);controls.set(f.id,{row,input,clear,group});
   }
  }
  if(!groups.includes(category))category='';$('save-bar').hidden=false;update();
 }
 async function load(){if(busy)return;try{error('');$('reload-config').disabled=true;const data=await request('/api/config',{timeout:18000});model=data;render();FrameUI.connection(true);}catch(e){error(e.message);if(!model)$('config-count').textContent='Configuration could not be loaded.';}finally{$('reload-config').disabled=false;}}
 $('reload-config').addEventListener('click',()=>{if(!edits().length||confirm('Reload configuration and discard your unsaved changes?'))load();});
 $('discard-config').addEventListener('click',()=>{if(confirm('Discard your unsaved changes?'))render();});
 $('config-search').addEventListener('input',filter);$('changed-only').addEventListener('change',filter);$('config-category').addEventListener('change',()=>{category=$('config-category').value;filter();});
 $('config-form').addEventListener('submit',e=>{e.preventDefault();if(busy)return;for(const c of controls.values())if(!c.input.checkValidity()){category='';$('config-search').value='';$('changed-only').checked=false;filter();c.group.open=true;c.input.reportValidity();c.input.focus();return;}
  const changed=edits();if(!changed.length)return;$('review-list').replaceChildren();for(const f of changed){const row=node('div',undefined,'review-change');row.append(node('strong',f.label),node('small',f.id));const v=value(f);const text=f.secret?(v.clear?'Clear saved value':'Replace saved value'):f.type==='boolean'?(v?'Enabled':'Disabled'):f.type==='list'?(v.join('\n')||'Empty list'):String(v);row.append(node('div',text||'Empty value','review-value'));if(f.restart)row.append(node('small','Applies after restarting the frame.'));$('review-list').append(row);}
  $('review-note').textContent=changed.some(f=>f.restart)?'Some changes need a restart. You can restart the frame after saving.':'These changes apply while your frame keeps playing.';$('config-review').showModal();
 });
 $('cancel-review').addEventListener('click',()=>$('config-review').close());$('config-review').addEventListener('cancel',e=>{if(busy)e.preventDefault();});
 $('save-config').addEventListener('click',async()=>{if(busy)return;const changed=edits(),fields={revision:model.revision};let newKey;
  for(const f of changed){const v=value(f);if(f.secret){if(v.clear)fields['clear.'+f.id]='1';else fields[f.id]=v.value;if(f.id==='remote.api_key')newKey=v.clear?'':v.value;}else fields[f.id]=f.type==='list'?JSON.stringify(v):f.type==='boolean'?(v?'1':'0'):String(v);}
  setBusy(true);try{const result=await request('/api/config',{fields,timeout:30000});if(newKey!==undefined)FrameUI.setKey(newKey);$('config-review').close();$('restart-notice').hidden=!result.restart_required;toast('Configuration saved to your frame.');setBusy(false);await load();}catch(e){$('config-review').close();error(e.message);setBusy(false);$('config-error').scrollIntoView({block:'center'});}
 });
 $('restart-frame').addEventListener('click',async()=>{if(!confirm('Restart piTrove to apply the saved configuration? Playback will resume automatically.'))return;const b=$('restart-frame');b.disabled=true;try{await request('/api/restart');toast('Restarting the frame…');}catch(e){error(e.message);}finally{setTimeout(()=>b.disabled=false,5000);}});
 window.addEventListener('beforeunload',e=>{if(edits().length){e.preventDefault();e.returnValue='';}});FrameUI.onUnlock(load);load();
 async function connection(){if(!document.hidden){try{await request('/api/status',{protected:false});FrameUI.connection(true);}catch{FrameUI.connection(false);}}setTimeout(connection,5000);}setTimeout(connection,5000);
})();
</script>
)CONFIG"+webui::end(version);
}
